from typing import *
from collections import *

class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)
        ans = 0

        for l, r, v in queries:
            if sum(nums[l:r+1]) % v != 0:
                return -1

            ans += (r-l+1)//v

        return ans
